def get_number(prompt):
    """Get a number from user input."""
    while True:
        try:
            num = float(input(prompt))
            return num
        except ValueError:
            print("That's not a valid number. Please try again.")

def get_operation():
    """Get the arithmetic operation from user input."""
    while True:
        operation = input("Enter the operation (+, -, *, /): ").strip()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("That's not a valid operation. Please try again.")

def perform_operation(num1, num2, operation):
    """Perform the given arithmetic operation on two numbers."""
    if operation == '+':
        return num1 + num2
    elif operation == '-':
        return num1 - num2
    elif operation == '*':
        return num1 * num2
    elif operation == '/':
        return num1 / num2

def main():
