    result_dict = {
        'Sum': num1 + num2,
        'Difference': num1 - num2,
        'Product': num1 * num2,
        'Quotient': num1 / num2 if num2 != 0 else "Division by zero is not allowed."
    }

    print("{:^10} {:^10} {:^10} {:^10}".format("Sum", "Difference", "Product", "Quotient"))
